class fdostream
    : private boost::base_from_member<fdoutbuf>   // constructed first
    , public std::ostream
{
    using pbase = boost::base_from_member<fdoutbuf>;
public:
    explicit fdostream(int fd)
        : pbase(fd)                // the hidden based-member exists
        , std::ostream(&member) {} // the dependent base is bound to it
};

struct fdostream_pbase {              // the helper, hand-written
    fdoutbuf sbuffer;                 // the based-member lives here
    explicit fdostream_pbase(int fd) : sbuffer(fd) {}
};

class fdostream
    : private fdostream_pbase         // declared first => constructed first
    , public std::ostream
{
public:
    explicit fdostream(int fd)
        : fdostream_pbase(fd), std::ostream(&sbuffer) {}
};

